//pagina designers
[data-namespace="designers"] {

    .contents {
        section.titolo-intro{
            @media (min-width: $breakpoint-large) {
                >* {
                    max-width: 1200px;
                }

            }
            span.br{
                display: none;
            }
            @media (max-width: $breakpoint-small) {
                span.br{
                    height: 55px;
                    width: 1px;
                    overflow: hidden;
                    display: inline-block;
                    br{
                        display: block;
                    }
                }
            }
        }

        div.sketch{
            overflow: hidden;
            position: absolute;
            top: 175px;
            right:0;
            width: 50%;
            max-width: 230px;
            opacity: .5;
            @media (min-width: $breakpoint-small) {
                top: 70px;
                right:8%;
            }
            @media (min-width: $breakpoint-locomotive) {
                top: 400px;
                max-width: 344px;                
            }
            img{
                margin-left: 60px;
                @media (min-width: $breakpoint-small) {
                    margin-left: 0;
                }
                @media (min-width: $breakpoint-locomotive) {
                    margin-left: 0
                }
            }
        }
        section.gallery{
            padding: 5px 0;
            @media (min-width: $breakpoint-locomotive) {
                padding: 50px 0;
            }
            .swiper-container-free-mode{
                overflow: hidden;
                height: 415px;
                @media (min-width: $breakpoint-locomotive) {
                    height: 550px;
                }
                @media (min-width: $breakpoint-large) {
                    height: 760px;
                }
            }

            .swiper-slide{
                @media (min-width: $breakpoint-large) {
                    width: 450px;
                }
                //immagine
                a.img{
                    display: block;
                    overflow: hidden;
                    img{
                        transform: scale(1.2);
                        transition: opacity 1.2s cubic-bezier(.215,.61,.355,1), 
                                    transform 1.2s cubic-bezier(.215,.61,.355,1);
                    }

                     html.no-touch & {
                        &:hover{
                            img{
                                transition-delay: 0s!important;
                                transform: scale(1.05);
                            }
                        }
                    }
                }

                //testi
                span{
                    font-size:15px;
                    margin-top: 5px;
                    display: block;
                    a{
                        @include a-underline($col-nero);
                        margin-right: 15px;
                    }
                }
            }
        }

        section.lista{

            width: 90%;
            max-width: 1100px;
            margin: 0 auto;
            padding: 50px 0 150px 0;
            ul{
                margin: 0;
                padding: 0;
                li{
                    display: inline;
                    a{
                        font-size: 22px;
                        font-weight: 500;
                        text-transform: uppercase;
                        color: $col-oro;
                        white-space: normal;
                        margin-right: 5px;
                        html.no-touch & {
                            @media (max-width: $breakpoint-medium-max) {
                                &:hover{
                                    text-decoration: underline;
                                }
                            }
                        }
                        @media (min-width: $breakpoint-large) {
                            margin-right: 25px;
                            font-size: 35px;
                            white-space: nowrap;
                            html.no-touch & {
                                @include a-underline($col-oro);
                            }
                        }
                    }
                    &:nth-child(odd){
                        a{
                            color: $col-nero;
                            @media (min-width: $breakpoint-large) {
                                html.no-touch & {
                                    @include a-underline($col-nero);
                                }
                            }
                        }
                    }
                }
            }
        }

    }

}

