    //all
    section.next{
        background-color: $col-bianco;
        border-top: 1px solid $col-grigio;
        border-bottom: 1px solid $col-grigio;
        padding: 50px 0;
        text-align: center;
        @media (min-width: $breakpoint-locomotive) {
            padding: 100px 0;
        }
        a{
            display: block;
            span{
                display: block;
                opacity: .5;
                margin-bottom: 25px;
            }
            .titolo{
                transition: opacity .3s ease-in-out;
                will-change: opacity;
                text-transform: uppercase;
                font-size:30px;
                line-height: 100%;
                @media (min-width: $breakpoint-large) {
                    font-size:54px;
                }

            }
            &:hover{
                .titolo{
                    opacity: .5;
                }
            }
        }

    }


}

